CREATE DATABASE IF NOT EXISTS petshop_central CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE petshop_central;
CREATE TABLE IF NOT EXISTS funcionarios (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, usuario VARCHAR(80) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL, perfil VARCHAR(40) NOT NULL DEFAULT 'Atendente', ativo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS clientes (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, cpf VARCHAR(14), telefone VARCHAR(20), email VARCHAR(150), criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pets (id INT AUTO_INCREMENT PRIMARY KEY, cliente_id INT NOT NULL, nome VARCHAR(100) NOT NULL, especie VARCHAR(50) NOT NULL, raca VARCHAR(80), porte VARCHAR(20), nascimento DATE, peso DECIMAL(7,2), CONSTRAINT fk_pet_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS servicos (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, descricao VARCHAR(500), valor DECIMAL(10,2) NOT NULL, duracao_minutos INT NOT NULL, ativo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS atendimentos (id INT AUTO_INCREMENT PRIMARY KEY, pet_id INT NOT NULL, servico_id INT NOT NULL, data_hora DATETIME NOT NULL, valor DECIMAL(10,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Agendado', observacoes VARCHAR(500), CONSTRAINT fk_atendimento_pet FOREIGN KEY (pet_id) REFERENCES pets(id) ON DELETE RESTRICT, CONSTRAINT fk_atendimento_servico FOREIGN KEY (servico_id) REFERENCES servicos(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS caixas (id INT AUTO_INCREMENT PRIMARY KEY, funcionario_id INT NULL, aberto_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, fechado_em DATETIME NULL, saldo_inicial DECIMAL(10,2) NOT NULL DEFAULT 0, saldo_final DECIMAL(10,2) NULL, status VARCHAR(20) NOT NULL DEFAULT 'Aberto', FOREIGN KEY(funcionario_id) REFERENCES funcionarios(id));
